cases.setup:
CREATE TABLE books (
  id INTEGER PRIMARY KEY,
  title TEXT NOT NULL,
  author TEXT,
  year INTEGER
);
INSERT INTO books (title, author, year) VALUES
  ('Отцы и дети', 'Тургенев', 1862),
  ('Ревизор', 'Гоголь', 1836),
  ('Обломов', 'Гончаров', 1859);

solution:
SELECT title, year FROM books
ORDER BY year
LIMIT 2;
